package com.openimage.common; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.stereotype.*; import org.springframework.web.filter.*; import java.io.*; @Component public class RequestIdFilter extends OncePerRequestFilter{protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{res.setHeader("X-Request-Id",RequestIds.create()); try{chain.doFilter(req,res);}finally{RequestIds.clear();}}}
